INSERT INTO releases (version, title, notes, released_at) VALUES ('v0.5.1', 'Boost Deal Confidence', ARRAY['New admin tool: Boost Deal Confidence runs additional MCTS simulations on low-confidence deals', 'Klondike: 200 additional sims, FreeCell: 50 additional sims per deal', 'Priority order: starter Easy → starter Medium → fresh Easy → fresh Medium → Hard → Expert', 'Never downgrades confidence — only improves scores upward', 'Live progress display with stop button for client-side processing', 'Recalculates DDS if min_solution_length changes by more than 5 points', 'New update_deal_confidence admin action in edge function'], '2025-03-25T14:00:00Z');